            with patch.object(signal, "pidfd_send_signal",
                              fake_send), (
                    patch.object(emit, "_fixture_signal",
                                 fake_helper)), (
                    patch.object(emit, "_fixture_escalate_subject",
                                 fake_escalate_subject)):
                emit._FixtureProcess._escalate(escalate_fake(state))

